function f = thrust_control_fixture()
%THRUST_CONTROL_FIXTURE 构造推力传递单元测试数据；无输入，输出总线、导航与三级参数。
p = shc09_parameters();
trim = shc09_hover_equilibrium(p);
g = control_defaults();
f.bus = struct('topics', aero_topic_bus(), 'command', trim.command);
specs = topic_specs();
for k=1:numel(specs)
    f.bus.topics.register(specs{k}.name, specs{k}.spec);
end
f.nav = struct('position',zeros(3,1),'velocity',zeros(3,1), ...
    'acceleration',zeros(3,1),'quaternion',[1;0;0;0], ...
    'omega',[0.1;-0.2;0.05],'alpha',[0.02;0.03;-0.01], ...
    'sample_time_s',0,'ideal',1);
f.attitude = struct('nav_topic','navigation/state','attitude_topic','control/attitude_setpoint', ...
    'output_topic','control/rate_setpoint','attitude',g.attitude,'rates',g.rates);
f.rate = struct('nav_topic','navigation/state','rate_topic','control/rate_setpoint', ...
    'allocation_topic','control/allocation_status','output_topic','control/torque_setpoint', ...
    'thrust_topic','control/thrust_setpoint','rate',g.rate,'rates',g.rates);
geometry = shc09_control_surface_geometry(p);
f.allocation = struct('torque_topic','control/torque_setpoint', ...
    'thrust_topic','control/thrust_setpoint','status_topic','control/allocation_status', ...
    'B_M',geometry.B_M,'l1_m',p.l1_m,'l2_m',p.l2_m, ...
    'servo_torque_coefficient',p.servo_torque_coefficient,'trim_delta_rad',trim.delta_rad, ...
    'delta_limit',p.servo_effective_range_rad,'diffuser_ratio',p.diffuser_ratio, ...
    'air_density',p.air_density_kg_m3,'disc_area',p.disc_area_m2,'k_T0',p.duct.k_T0, ...
    'max_thrust_n',p.duct.k_T0*p.motor_device.omega_range_rad_s(2)^2, ...
    'motor_min_rad_s',p.motor_device.omega_range_rad_s(1), ...
    'motor_max_rad_s',p.motor_device.omega_range_rad_s(2), ...
    've_min_m_s',g.allocation.ve_min_m_s,'saturation_tolerance',g.rate.saturation_tolerance);
f.trim = trim;
end
